// static
bool StructTraits<::ash::libassistant::mojom::AuthenticationToken::DataView, ::ash::libassistant::mojom::AuthenticationTokenPtr>::Read(
    ::ash::libassistant::mojom::AuthenticationToken::DataView input,
    ::ash::libassistant::mojom::AuthenticationTokenPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::AuthenticationTokenPtr result(::ash::libassistant::mojom::AuthenticationToken::New());
  
      if (success && !input.ReadGaiaId(&result->gaia_id))
        success = false;
      if (success && !input.ReadAccessToken(&result->access_token))
        success = false;
  *output = std::move(result);
  return success;
}

