SettingsControllerAsyncWaiter::SettingsControllerAsyncWaiter(
    SettingsController* proxy) : proxy_(proxy) {}

SettingsControllerAsyncWaiter::~SettingsControllerAsyncWaiter() = default;

void SettingsControllerAsyncWaiter::GetSettings(
    const std::string& selector, bool include_header, std::string* out_result) {
  base::RunLoop loop;
  proxy_->GetSettings(std::move(selector),std::move(include_header),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_result
,
             const std::string& result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

std::string SettingsControllerAsyncWaiter::GetSettings(
    const std::string& selector, bool include_header) {
  std::string async_wait_result;
  GetSettings(std::move(selector),std::move(include_header),&async_wait_result);
  return async_wait_result;
}

void SettingsControllerAsyncWaiter::UpdateSettings(
    const std::string& settings, std::string* out_result) {
  base::RunLoop loop;
  proxy_->UpdateSettings(std::move(settings),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_result
,
             const std::string& result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

std::string SettingsControllerAsyncWaiter::UpdateSettings(
    const std::string& settings) {
  std::string async_wait_result;
  UpdateSettings(std::move(settings),&async_wait_result);
  return async_wait_result;
}






